import re, shlex

# These are local execution-policy checks, not CTF solution rules.
# The command is still generated by the model.
BLOCKED = [
    r'\brm\s+-rf\s+/', r'\bmkfs\b', r'\bshutdown\b', r'\breboot\b',
    r'\bpoweroff\b', r'\bhalt\b', r':\(\)\s*\{', r'\bkill\s+-9\s+-1\b'
]

def validate_command(command):
    c = command.strip()
    if not c:
        return False, "empty command"
    if len(c) > 2000:
        return False, "command too long"
    if "\n" in c or "\r" in c:
        return False, "multiline command not allowed"
    for pattern in BLOCKED:
        if re.search(pattern, c, re.I):
            return False, "blocked destructive command"
    return True, ""

def normalize(c):
    return " ".join(c.strip().split())
